import{_ as t,o as r,c as a,ag as o}from"./chunks/framework.BIas3y6W.js";const p=JSON.parse('{"title":"Research behind the course","description":"","frontmatter":{"source":"research/README.md"},"headers":[],"relativePath":"research/index.md","filePath":"research/index.md"}'),s={name:"research/index.md"};function n(i,e,d,h,c,l){return r(),a("div",null,[...e[0]||(e[0]=[o('<h1 id="research-behind-the-course" tabindex="-1">Research behind the course <a class="header-anchor" href="#research-behind-the-course" aria-label="Permalink to &quot;Research behind the course&quot;">​</a></h1><p>Building Apps with AI was designed from a review, carried out in September 2026, of how other courses teach AI-assisted programming, what the evidence says about learning with AI, what goes wrong in vibe-coded software, and which tools are free. An update in October 2026 re-checked every tool and added the studies, incidents and courses published in between; together with a review of the course itself, it shaped the October 2026 revision. In November 2026 the instructor split the course in two (this course, for students from any major after one programming course, and an upper-division course, Engineering Software with AI, for CS seniors and graduate students) and moved this one from eight accelerated weeks to a 16-week semester. That restructure added no new research; the reports and notes below are left as written, so their week numbers are those of the eight-week course (old week N is now weeks 2N−1 and 2N).</p><table tabindex="0"><thead><tr><th>File</th><th>What it is</th></tr></thead><tbody><tr><td><a href="./design-rationale.html">Why the Course Looks Like This</a></td><td><strong>Start here.</strong> Each design decision in the course, the evidence behind it, and where it shows up. Its <a href="./design-rationale.html#november-2026-update">November 2026 update</a> and <a href="./design-rationale.html#october-2026-update">October 2026 update</a> map each change in those revisions to its reasons and evidence.</td></tr><tr><td><a href="./landscape-report-2026-09.html">Teach the Loop, Not the Tool</a></td><td>The full research report, &quot;Teach the Loop, Not the Tool&quot; (about 9,000 words, 160+ sources).</td></tr><tr><td><a href="./landscape-update-2026-10.html">Free Tiers Shrink While Evidence Demands Friction</a></td><td>The October update, &quot;Free Tiers Shrink While Evidence Demands Friction&quot; (25 September – 21 October 2026): new learning studies, the year&#39;s incidents, every TOOLS.md row re-checked, and five tiers of recommended fixes.</td></tr><tr><td><a href="./notes/university-courses.html">University and College Courses on AI-Assisted Programming, &quot;Vibe Coding&quot;, and Agentic Software Development (2024 to Sept 2026)</a></td><td>Notes on university courses: Stanford CS146S, CMU 15-113 and 17-316, UChicago, Utah, Michigan, UCSD, Northeastern, Harvard CS50 and others.</td></tr><tr><td><a href="./notes/online-industry-courses.html">Online, Industry, MOOC, Bootcamp and Cohort Courses on Vibe Coding and AI-Assisted Coding (2025 to Sept 2026)</a></td><td>Notes on about 40 online, industry and cohort courses: DeepLearning.AI, Anthropic, Google/Kaggle, Microsoft, Coursera, Maven, Campus × Replit and others.</td></tr><tr><td><a href="./notes/pedagogy-practices-risks.html">Teaching and Practicing AI-Assisted Programming / Vibe Coding: Evidence, Practitioner Consensus, and Risks (2023 – Sept 2026)</a></td><td>Education research, productivity studies, practitioner workflows, and security and safety incidents.</td></tr><tr><td><a href="./notes/tools-chat-and-app-builders.html">Free and Low-Cost AI Chat Assistants, Browser App Builders, and Student Programs for a &quot;Vibe Coding 101&quot; Course (as of 25 September 2026)</a></td><td>Free and basic tiers of chat assistants and browser app builders, student offers, privacy and age rules.</td></tr><tr><td><a href="./notes/tools-ide-cli-apis-hosting.html">Free and cheap tools for &quot;Vibe Coding 101&quot;: AI IDEs, CLI agents, free LLM APIs, and free hosting/backends (verified 2026-09-25)</a></td><td>Free and basic tiers of AI editors, terminal agents, LLM APIs, hosting and databases; AGENTS.md and MCP support.</td></tr></tbody></table><h3 id="october-2026-notes" tabindex="-1">October 2026 notes <a class="header-anchor" href="#october-2026-notes" aria-label="Permalink to &quot;October 2026 notes&quot;">​</a></h3><p>Each of these records only what is new since the September notes above, or what those notes missed.</p><table tabindex="0"><thead><tr><th>File</th><th>What it is</th></tr></thead><tbody><tr><td><a href="./notes/2026-10/evidence-incidents-practices.html">Evidence, Incidents and Practitioner Guidance Update for Vibe Coding 101 (25 Sep – 21 Oct 2026, plus earlier-2026 items the baseline missed)</a></td><td>New learning studies (recall, ownership, AI-off maintenance, a large AI-tutor trial), productivity and code-security evidence, the 2026 incidents behind the new case studies, standards and practice updates, and legal and policy changes.</td></tr><tr><td><a href="./notes/2026-10/university-courses-fall-2026.html">University and College Courses on AI-Assisted Programming / Vibe Coding / Agentic SE: What Is New, 25 Sept – 21 Oct 2026</a></td><td>Fall 2026 university courses: Stanford CS146S weeks 2–4, Michigan EECS 498&#39;s hackathon and Elephant-Goldfish Model, CMU 15-113&#39;s fall survey, new non-major studios and the SIGCSE 2027 program.</td></tr><tr><td><a href="./notes/2026-10/online-courses-and-learner-feedback.html">Online, Industry, MOOC, Bootcamp, Cohort and Vendor-Academy Courses on Vibe Coding: What Is New (25 Sept to 21 Oct 2026), Plus Fresh Learner Feedback</a></td><td>New or updated online and vendor courses (GitHub Copilot app for Beginners, DeepLearning.AI&#39;s cloud-to-local course, Anthropic Academy) and fresh learner reviews.</td></tr><tr><td><a href="./notes/2026-10/tool-changes-since-september.html">Tool changes since 25 September 2026: row-by-row verification of TOOLS.md (checked 21 October 2026)</a></td><td>A row-by-row re-check of TOOLS.md on 21 October 2026, with dated changes to watch.</td></tr></tbody></table><h2 id="how-to-read-the-notes" tabindex="-1">How to read the notes <a class="header-anchor" href="#how-to-read-the-notes" aria-label="Permalink to &quot;How to read the notes&quot;">​</a></h2><ul><li>Every fact carries a link and, where available, a date. Facts about tools were checked on <strong>25 September 2026</strong> (September notes) and <strong>21 October 2026</strong> (October notes) and will go stale. The course keeps current numbers only in <a href="./../TOOLS.html">Tool Handout</a>.</li><li>Notes mark third-party or search-snippet sources and flag conflicting sources. The reports&#39; &quot;gaps&quot; paragraphs list what could not be verified.</li><li>The notes were compiled with AI research assistants and then synthesized. Treat them as a well-sourced starting point, and follow the links before relying on any single claim.</li></ul>',8)])])}const g=t(s,[["render",n]]);export{p as __pageData,g as default};
